test('unreconciled reservation stays counted after restart', () => {
  const dir: string = fs.mkdtempSync(path.join(os.tmpdir(), 'meta-ledger-'));
  try {
    let nextId: number = 0;
    const newId = (): string => {
      nextId += 1;
